// HasRawMaterials applies the HasEdge predicate on the "raw_materials" edge.
func HasRawMaterials() predicate.ProductionBatch {
	return predicate.ProductionBatch(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RawMaterialsTable, RawMaterialsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRawMaterialsWith applies the HasEdge predicate on the "raw_materials" edge with a given conditions (other predicates).
func HasRawMaterialsWith(preds ...predicate.BatchRawMaterial) predicate.ProductionBatch {
	return predicate.ProductionBatch(func(s *sql.Selector) {
		step := newRawMaterialsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

